from pathlib import Path
import sys

path=Path(sys.argv[1]); variant=sys.argv[2]
if variant not in {'attack','movegen','all'}: raise SystemExit('bad variant')
s=path.read_text()

anchor='KNIGHT_TARGETS, KNIGHT_TARGET_COUNTS = _build_fixed_targets(KNIGHT_STEPS)\nKING_TARGETS, KING_TARGET_COUNTS = _build_fixed_targets(KING_STEPS)\n'
insert='''KNIGHT_TARGETS, KNIGHT_TARGET_COUNTS = _build_fixed_targets(KNIGHT_STEPS)\nKING_TARGETS, KING_TARGET_COUNTS = _build_fixed_targets(KING_STEPS)\n\n\ndef _build_slider_rays() -> tuple[np.ndarray, np.ndarray]:\n    # Direction order exactly preserves the existing bishop-then-rook move order.\n    directions = BISHOP_DIRS + ROOK_DIRS\n    rays = np.full((64, 8, 7), -1, dtype=np.int8)\n    counts = np.zeros((64, 8), dtype=np.int8)\n    for square in range(64):\n        file = square & 7\n        rank = square >> 3\n        for direction, (delta_file, delta_rank) in enumerate(directions):\n            f = file + delta_file\n            r = rank + delta_rank\n            count = 0\n            while 0 <= f < 8 and 0 <= r < 8:\n                rays[square, direction, count] = r * 8 + f\n                count += 1\n                f += delta_file\n                r += delta_rank\n            counts[square, direction] = count\n    return rays, counts\n\n\nSLIDER_RAYS, SLIDER_RAY_COUNTS = _build_slider_rays()\n'''
if anchor not in s: raise SystemExit('target anchor missing')
s=s.replace(anchor,insert,1)

def replace_function(src,name,new):
    pos=src.find(f'def {name}(')
    if pos<0: raise SystemExit(f'missing {name}')
    start=src.rfind('@njit',0,pos)
    if start<0: raise SystemExit(f'no decorator {name}')
    end=src.find('\n\n@njit',pos)
    if end<0: raise SystemExit(f'no next decorator {name}')
    return src[:start]+new.rstrip()+src[end:]

ATTACK='''@njit(cache=False)\ndef is_square_attacked(board: np.ndarray, target: int, by_side: int) -> bool:\n    target_file = target & 7\n    target_rank = target >> 3\n\n    source_rank = target_rank - by_side\n    if 0 <= source_rank < 8:\n        for delta_file in (-1, 1):\n            source_file = target_file - delta_file\n            if 0 <= source_file < 8:\n                source = _square(source_file, source_rank)\n                if board[source] == by_side * PAWN:\n                    return True\n\n    for index in range(int(KNIGHT_TARGET_COUNTS[target])):\n        source = int(KNIGHT_TARGETS[target, index])\n        if board[source] == by_side * KNIGHT:\n            return True\n\n    for index in range(int(KING_TARGET_COUNTS[target])):\n        source = int(KING_TARGETS[target, index])\n        if board[source] == by_side * KING:\n            return True\n\n    # Rays 0..3 are bishop diagonals; 4..7 are rook orthogonals.\n    for direction in range(4):\n        for index in range(int(SLIDER_RAY_COUNTS[target, direction])):\n            source = int(SLIDER_RAYS[target, direction, index])\n            piece = int(board[source])\n            if piece != EMPTY:\n                if piece == by_side * BISHOP or piece == by_side * QUEEN:\n                    return True\n                break\n\n    for direction in range(4, 8):\n        for index in range(int(SLIDER_RAY_COUNTS[target, direction])):\n            source = int(SLIDER_RAYS[target, direction, index])\n            piece = int(board[source])\n            if piece != EMPTY:\n                if piece == by_side * ROOK or piece == by_side * QUEEN:\n                    return True\n                break\n\n    return False\n'''

CONTEXT='''@njit(cache=False, inline="never")\ndef _legality_context(\n    board: np.ndarray,\n    side: int,\n    own_king: int,\n) -> tuple[int, int, int, np.uint64]:\n    """Return ``(check_count, checker_square, checker_is_slider, pinned_mask)``."""\n    if own_king < 0:\n        return 2, -1, 0, np.uint64(0)\n\n    enemy = -side\n    king_file = own_king & 7\n    king_rank = own_king >> 3\n    check_count = 0\n    checker_square = -1\n    checker_is_slider = 0\n    pinned = np.uint64(0)\n\n    source_rank = king_rank - enemy\n    if 0 <= source_rank < 8:\n        for delta_file in (-1, 1):\n            source_file = king_file - delta_file\n            if 0 <= source_file < 8:\n                source = _square(source_file, source_rank)\n                if int(board[source]) == enemy * PAWN:\n                    check_count += 1\n                    checker_square = source\n                    checker_is_slider = 0\n\n    for index in range(int(KNIGHT_TARGET_COUNTS[own_king])):\n        source = int(KNIGHT_TARGETS[own_king, index])\n        if int(board[source]) == enemy * KNIGHT:\n            check_count += 1\n            checker_square = source\n            checker_is_slider = 0\n    for index in range(int(KING_TARGET_COUNTS[own_king])):\n        source = int(KING_TARGETS[own_king, index])\n        if int(board[source]) == enemy * KING:\n            check_count += 1\n            checker_square = source\n            checker_is_slider = 0\n\n    # One scan of each precomputed king ray finds both direct checks and absolute pins.\n    for direction in range(8):\n        blocker = -1\n        diagonal = direction < 4\n        for index in range(int(SLIDER_RAY_COUNTS[own_king, direction])):\n            square = int(SLIDER_RAYS[own_king, direction, index])\n            signed_piece = int(board[square])\n            if signed_piece == EMPTY:\n                continue\n            if signed_piece * side > 0:\n                if blocker < 0:\n                    blocker = square\n                    continue\n                break\n\n            kind = abs(signed_piece)\n            slider = kind == QUEEN or (diagonal and kind == BISHOP) or ((not diagonal) and kind == ROOK)\n            if slider:\n                if blocker < 0:\n                    check_count += 1\n                    checker_square = square\n                    checker_is_slider = 1\n                else:\n                    pinned |= np.uint64(1) << np.uint64(blocker)\n            break\n\n    return check_count, checker_square, checker_is_slider, pinned\n'''

PSEUDO='''@njit(cache=False)\ndef generate_pseudo_moves_into(\n    board: np.ndarray,\n    side: int,\n    castling: int,\n    ep_square: int,\n    moves: np.ndarray,\n) -> int:\n    count = 0\n\n    for from_square in range(64):\n        signed_piece = int(board[from_square])\n        if signed_piece * side <= 0:\n            continue\n        piece = signed_piece * side\n        file = from_square & 7\n        rank = from_square >> 3\n\n        if piece == PAWN:\n            next_rank = rank + side\n            if 0 <= next_rank < 8:\n                one_step = _square(file, next_rank)\n                if board[one_step] == EMPTY:\n                    count = _append_pawn_target(moves, count, from_square, one_step, next_rank == (7 if side == WHITE else 0), 0)\n                    start_rank = 1 if side == WHITE else 6\n                    if rank == start_rank:\n                        two_rank = rank + 2 * side\n                        two_step = _square(file, two_rank)\n                        if board[two_step] == EMPTY:\n                            count = _append(moves, count, encode_move(from_square, two_step, 0, FLAG_DOUBLE))\n                for delta_file in (-1, 1):\n                    target_file = file + delta_file\n                    if not 0 <= target_file < 8:\n                        continue\n                    target = _square(target_file, next_rank)\n                    target_piece = int(board[target])\n                    if target_piece * side < 0 and abs(target_piece) != KING:\n                        count = _append_pawn_target(moves, count, from_square, target, next_rank == (7 if side == WHITE else 0), 0)\n                    elif target == ep_square and target_piece == EMPTY:\n                        count = _append(moves, count, encode_move(from_square, target, 0, FLAG_EP))\n            continue\n\n        if piece == KNIGHT:\n            for index in range(int(KNIGHT_TARGET_COUNTS[from_square])):\n                target = int(KNIGHT_TARGETS[from_square, index])\n                target_piece = int(board[target])\n                if target_piece * side <= 0 and abs(target_piece) != KING:\n                    count = _append(moves, count, encode_move(from_square, target))\n            continue\n\n        if piece == KING:\n            for index in range(int(KING_TARGET_COUNTS[from_square])):\n                target = int(KING_TARGETS[from_square, index])\n                target_piece = int(board[target])\n                if target_piece * side <= 0 and abs(target_piece) != KING:\n                    count = _append(moves, count, encode_move(from_square, target))\n            if not is_square_attacked(board, from_square, -side):\n                if side == WHITE and from_square == 4:\n                    if castling & CASTLE_WK and board[5] == EMPTY and board[6] == EMPTY and board[7] == ROOK and not is_square_attacked(board, 5, BLACK) and not is_square_attacked(board, 6, BLACK):\n                        count = _append(moves, count, encode_move(4, 6, 0, FLAG_CASTLE))\n                    if castling & CASTLE_WQ and board[1] == EMPTY and board[2] == EMPTY and board[3] == EMPTY and board[0] == ROOK and not is_square_attacked(board, 3, BLACK) and not is_square_attacked(board, 2, BLACK):\n                        count = _append(moves, count, encode_move(4, 2, 0, FLAG_CASTLE))\n                elif side == BLACK and from_square == 60:\n                    if castling & CASTLE_BK and board[61] == EMPTY and board[62] == EMPTY and board[63] == -ROOK and not is_square_attacked(board, 61, WHITE) and not is_square_attacked(board, 62, WHITE):\n                        count = _append(moves, count, encode_move(60, 62, 0, FLAG_CASTLE))\n                    if castling & CASTLE_BQ and board[57] == EMPTY and board[58] == EMPTY and board[59] == EMPTY and board[56] == -ROOK and not is_square_attacked(board, 59, WHITE) and not is_square_attacked(board, 58, WHITE):\n                        count = _append(moves, count, encode_move(60, 58, 0, FLAG_CASTLE))\n            continue\n\n        if piece == BISHOP:\n            first_direction, last_direction = 0, 4\n        elif piece == ROOK:\n            first_direction, last_direction = 4, 8\n        else:\n            first_direction, last_direction = 0, 8\n        for direction in range(first_direction, last_direction):\n            for index in range(int(SLIDER_RAY_COUNTS[from_square, direction])):\n                target = int(SLIDER_RAYS[from_square, direction, index])\n                target_piece = int(board[target])\n                if target_piece == EMPTY:\n                    count = _append(moves, count, encode_move(from_square, target))\n                else:\n                    if target_piece * side < 0 and abs(target_piece) != KING:\n                        count = _append(moves, count, encode_move(from_square, target))\n                    break\n\n    return count\n'''

TACT='''@njit(cache=False)\ndef generate_pseudo_tactical_moves_into(\n    board: np.ndarray,\n    side: int,\n    ep_square: int,\n    moves: np.ndarray,\n) -> int:\n    """Generate captures, en-passant and promotions in normal pseudo-move order."""\n    count = 0\n    for from_square in range(64):\n        signed_piece = int(board[from_square])\n        if signed_piece * side <= 0:\n            continue\n        piece = signed_piece * side\n        file = from_square & 7\n        rank = from_square >> 3\n\n        if piece == PAWN:\n            next_rank = rank + side\n            if 0 <= next_rank < 8:\n                one_step = _square(file, next_rank)\n                if next_rank == (7 if side == WHITE else 0) and board[one_step] == EMPTY:\n                    count = _append_pawn_target(moves, count, from_square, one_step, True, 0)\n                for delta_file in (-1, 1):\n                    target_file = file + delta_file\n                    if not 0 <= target_file < 8:\n                        continue\n                    target = _square(target_file, next_rank)\n                    target_piece = int(board[target])\n                    if target_piece * side < 0 and abs(target_piece) != KING:\n                        count = _append_pawn_target(moves, count, from_square, target, next_rank == (7 if side == WHITE else 0), 0)\n                    elif target == ep_square and target_piece == EMPTY:\n                        count = _append(moves, count, encode_move(from_square, target, 0, FLAG_EP))\n            continue\n\n        if piece == KNIGHT:\n            for index in range(int(KNIGHT_TARGET_COUNTS[from_square])):\n                target = int(KNIGHT_TARGETS[from_square, index])\n                target_piece = int(board[target])\n                if target_piece * side < 0 and abs(target_piece) != KING:\n                    count = _append(moves, count, encode_move(from_square, target))\n            continue\n\n        if piece == KING:\n            for index in range(int(KING_TARGET_COUNTS[from_square])):\n                target = int(KING_TARGETS[from_square, index])\n                target_piece = int(board[target])\n                if target_piece * side < 0 and abs(target_piece) != KING:\n                    count = _append(moves, count, encode_move(from_square, target))\n            continue\n\n        if piece == BISHOP:\n            first_direction, last_direction = 0, 4\n        elif piece == ROOK:\n            first_direction, last_direction = 4, 8\n        else:\n            first_direction, last_direction = 0, 8\n        for direction in range(first_direction, last_direction):\n            for index in range(int(SLIDER_RAY_COUNTS[from_square, direction])):\n                target = int(SLIDER_RAYS[from_square, direction, index])\n                target_piece = int(board[target])\n                if target_piece != EMPTY:\n                    if target_piece * side < 0 and abs(target_piece) != KING:\n                        count = _append(moves, count, encode_move(from_square, target))\n                    break\n    return count\n'''

if variant in {'attack','all'}:
    s=replace_function(s,'is_square_attacked',ATTACK)
    s=replace_function(s,'_legality_context',CONTEXT)
if variant in {'movegen','all'}:
    s=replace_function(s,'generate_pseudo_moves_into',PSEUDO)
    s=replace_function(s,'generate_pseudo_tactical_moves_into',TACT)
path.write_text(s)
print('patched ray core',variant)
